# This generator targets Catch2 test spec/tag strings consumed via FUZZ_PARAM_STR
# in the provided fuzzer stub. The stub:
# - Reads a string from FUZZ_PARAM_STR, truncates to 32 chars, assigns into ConfigData.testsOrTags.
# - Also flips some small flags using FUZZ_PARAM(unsigned int), but these do not
#   depend on our buffer content here.
# Therefore we generate a single interesting test spec/tag expression string
# serialized as bytes. The fuzzing harness will read it as a string input.
# We aim to create valid and diverse Catch2 test spec expressions to exercise
# parsing paths: tags in brackets, negations with ~, disjunction |, conjunction ,
# wildcards *, escaped names with quotes, section specifiers with '/':, and
# combinations thereof. We keep length <= 32.

_TAGS = [
    "[fast]", "[slow]", "[unit]", "[integration]", "[network]",
    "[db]", "[io]", "[math]", "[parser]", "[regression]",
]

_NAMES = [
    "foo", "bar", "baz", "alpha", "beta", "gamma", "delta",
    "parse_input", "compute*", "io/stream", "Section A", "case-01",
]

# Building blocks for expressions
def rand_tag(rng: random.Random) -> str:
    # Sometimes generate arbitrary custom tag in brackets
    if rng.random() < 0.3:
        core = rng.choice(_NAMES).replace(" ", "_")
        return f"[{core}]"
    return rng.choice(_TAGS)


def rand_name(rng: random.Random) -> str:
    # Generate a test name or pattern, possibly quoted if it contains spaces or special chars
    base = rng.choice(_NAMES)
    # Occasionally introduce wildcard or explicit pattern-like tokens
    if rng.random() < 0.25:
        # Append wildcard to increase pattern coverage
        if not base.endswith("*"):
            base = base + "*"
    # Add section selectors using '/'
    if rng.random() < 0.2:
        base = base + "/" + rng.choice(["sec1", "sec 2", "inner*", "A/B"])  # Catch2 interprets '/' as section path
    # Quote if contains spaces or slash + space
    if any(c in base for c in " \t\n\r\v\f,"):
        return f'"{base}"'
    return base


def maybe_negate(rng: random.Random, expr: str) -> str:
    return ("~" + expr) if rng.random() < 0.3 else expr


def join_exprs(rng: random.Random, parts: List[str]) -> str:
    # Combine using OR '|' or AND ',' with optional grouping via parentheses
    if not parts:
        return ""
    if len(parts) == 1:
        return parts[0]
    ops = []
    for _ in range(len(parts) - 1):
        ops.append(rng.choice(["|", ","]))
    expr = parts[0]
    for op, part in zip(ops, parts[1:]):
        expr += op + part
    if rng.random() < 0.35:
        expr = "(" + expr + ")"
    return expr


def build_spec(rng: random.Random) -> str:
    # Construct a moderately complex, but valid, spec expression under 32 chars.
    # Strategy:
    # - Randomly choose a pattern of tags and names
    # - Mix negations and operators
    # - Ensure final size <= 32 by trimming intelligently
    choices = []
    # Ensure at least one primary selector
    for _ in range(rng.randint(1, 3)):
        if rng.random() < 0.5:
            choices.append(maybe_negate(rng, rand_tag(rng)))
        else:
            choices.append(maybe_negate(rng, rand_name(rng)))
    expr = join_exprs(rng, choices)

    # Optionally append another small clause
    if rng.random() < 0.5:
        tail = maybe_negate(rng, rng.choice([rand_tag(rng), rand_name(rng)]))
        # Choose operator for the tail
        op = rng.choice(["|", ","]) if expr else ""
        expr = (expr + op + tail) if expr else tail

    # Occasionally group whole expression or add redundant parentheses
    if rng.random() < 0.2 and expr:
        expr = "(" + expr + ")"

    # Guarantee at least something simple if empty
    if not expr:
        expr = rng.choice(["[fast]", "foo", "~[slow]", "foo|bar"])  # all valid

    # Enforce max length 32: prefer trimming from trailing parts at operator boundaries
    if len(expr) > 32:
        # Try to keep validity: split on operators and rebuild until <= 32
        tokens = []
        buf = ""
        for ch in expr:
            if ch in "|,":
                if buf:
                    tokens.append(buf)
                    buf = ""
                tokens.append(ch)
            else:
                buf += ch
        if buf:
            tokens.append(buf)
        rebuilt = ""
        for t in tokens:
            if len(rebuilt) + len(t) <= 32:
                rebuilt += t
            else:
                break
        # Fallback: hard truncate if still empty
        expr = rebuilt if rebuilt else expr[:32]

    # Final sanity: strip whitespace outside quotes (Catch allows spaces but we keep concise)
    # Preserve quoted substrings
    def strip_outside_quotes(s: str) -> str:
        out = []
        in_quote = False
        for ch in s:
            if ch == '"':
                in_quote = not in_quote
                out.append(ch)
            else:
                if in_quote:
                    out.append(ch)
                else:
                    # collapse spaces around operators
                    if ch not in " \t\n\r\v\f":
                        out.append(ch)
        return "".join(out)

    expr = strip_outside_quotes(expr)

    # Ensure final length <= 32
    if len(expr) > 32:
        expr = expr[:32]

    return expr


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    spec = build_spec(rng)
    # Return as UTF-8 bytes; FUZZ_PARAM_STR will interpret raw bytes as string content
    return spec.encode("utf-8", errors="strict")

