# Fuzzer stub behavior summary (Catch::Detail::rawMemoryToString):
# - Sometimes calls with (p=nullptr, size=0)
# - Otherwise provides a std::string buf from FUZZ_PARAM_STR(), caps to 1024, and passes
#   p = buf.data(), and size chosen uniformly in [0, buf.size()].
# Our generator returns a bytes object to seed FUZZ_PARAM_STR with interesting, valid raw bytes.

MAX_TOTAL = 4096

_ascii_common = (
    b"The quick brown fox jumps over the lazy dog.\n"
    b"0123456789 abcdef ABCDEF\n"
    b"!@#$%^&*()_+-=[]{};:'\",.<>/?`~\n"
)

def _pattern_all(byte_val: int, n: int) -> bytes:
    return bytes([byte_val]) * n


def _pattern_incrementing(n: int, start: int = 0) -> bytes:
    return bytes(((start + i) & 0xFF for i in range(n)))


def _pattern_strided(n: int, stride: int) -> bytes:
    return bytes(((i * stride) & 0xFF for i in range(n)))


def _pattern_repeat(seq: bytes, n: int) -> bytes:
    if not seq:
        return b""
    reps, rem = divmod(n, len(seq))
    return seq * reps + seq[:rem]


def _mix_chunks(chunks: List[bytes], target_len: int, rnd: random.Random) -> bytes:
    out = bytearray()
    # Mix random slices from provided chunks, occasionally inserting NUL runs
    while len(out) < target_len and chunks:
        ch = rnd.choice(chunks)
        if not ch:
            continue
        a = rnd.randrange(0, len(ch))
        b = rnd.randrange(a, len(ch))
        piece = ch[a:b]
        if rnd.random() < 0.2:
            out.extend(b"\x00" * rnd.randrange(0, 4))
        out.extend(piece)
    return bytes(out[:target_len])


def _interesting_sizes(rnd: random.Random) -> int:
    # Favor edge sizes and include a random pick up to 1500 (stub caps to 1024)
    choices = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024]
    choices.append(rnd.randrange(0, 1501))
    return rnd.choice(choices)


def _make_ascii_blob(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    base = _pattern_repeat(_ascii_common, max(0, n))
    controls = bytes([0x07, 0x08, 0x09, 0x0A, 0x0D, 0x1B])
    ctrl_blob = _pattern_repeat(controls, n)
    return _mix_chunks([base, ctrl_blob], n, rnd)


def _make_binary_blob(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    pieces = []
    pieces.append(_pattern_all(0x00, n))
    pieces.append(_pattern_all(0xFF, n))
    pieces.append(_pattern_incrementing(n, start=rnd.randrange(0, 256)))
    pieces.append(_pattern_strided(n, stride=rnd.randrange(1, 17)))
    pieces.append(_pattern_repeat(b"\xDE\xAD\xBE\xEF", n))
    pieces.append(_pattern_repeat(b"\xBA\xAD\xF0\x0D", n))
    pieces.append(_pattern_repeat(b"\x00\xFF", n))
    blob = bytearray(rnd.choice(pieces))
    for off in range(0, len(blob), 16):
        if off + 8 <= len(blob) and rnd.random() < 0.3:
            val = rnd.getrandbits(64)
            blob[off:off+8] = struct.pack('<Q', val)
        if off + 4 <= len(blob) and rnd.random() < 0.3:
            val32 = rnd.getrandbits(32)
            blob[off:off+4] = struct.pack('<I', val32)
    if len(blob) > 0 and rnd.random() < 0.5:
        pos = rnd.randrange(0, len(blob))
        run = min(len(blob) - pos, rnd.randrange(1, 17))
        blob[pos:pos+run] = b"\x00" * run
    if len(blob) > 1 and rnd.random() < 0.3:
        for i in range(0, len(blob), 2):
            blob[i] = 0x00
            if i + 1 < len(blob):
                blob[i + 1] = 0xFF
    return bytes(blob[:n])


def _make_mixed_blob(rnd: random.Random, n: int) -> bytes:
    if n <= 0:
        return b""
    ascii_part = _make_ascii_blob(rnd, max(0, n // 2))
    bin_part = _make_binary_blob(rnd, n - len(ascii_part))
    return _mix_chunks([ascii_part, bin_part], n, rnd)


def generate(seed: int) -> bytes:
    rnd = random.Random(seed)

    kind = rnd.choice(["empty", "ascii", "binary", "mixed"])
    size = _interesting_sizes(rnd)

    if kind == "empty":
        size = 0
        data = b""
    elif kind == "ascii":
        data = _make_ascii_blob(rnd, size)
    elif kind == "binary":
        data = _make_binary_blob(rnd, size)
    else:
        data = _make_mixed_blob(rnd, size)

    if len(data) > MAX_TOTAL:
        data = data[:MAX_TOTAL]

    # Optionally add a simple header/footer to diversify content while staying valid bytes
    if len(data) > 0 and rnd.random() < 0.4:
        magic = 0xCACE0001
        header = struct.pack('<II', magic, len(data) & 0xFFFFFFFF)
        data = header + data
    if len(data) > 0 and rnd.random() < 0.4:
        footer = struct.pack('<I', (len(data) * 2654435761) & 0xFFFFFFFF)
        data = data + footer

    return data[:MAX_TOTAL]
